from pathlib import Path

MODULE_PATH = Path("/tmp/organize_downloads.py")

with open(MODULE_PATH, 'r', encoding='utf-8') as f:
    lines = f.readlines()

print(f"文件总行数: {len(lines)}")
print(f"文件总字符数: {sum(len(line) for line in lines)}")

# 检查格式问题
issues = []
for i, line in enumerate(lines, 1):
    # 检查 Tab
    if '\t' in line:
        issues.append(f"第 {i} 行包含 Tab 缩进")
    # 检查行尾空白（排除换行符）
    stripped = line.rstrip('\n').rstrip('\r')
    if stripped != stripped.rstrip(' '):
        issues.append(f"第 {i} 行行尾有多余空白")

if issues:
    print("\n发现格式问题:")
    for issue in issues:
        print(f"  ⚠ {issue}")
else:
    print("\n✓ 无 Tab 缩进")
    print("✓ 无行尾空白")

# 检查 from __future__ 位置
print("\n检查 from __future__ 导入位置:")
for i, line in enumerate(lines[:15], 1):
    if 'from __future__' in line:
        print(f"  第 {i} 行: {line.strip()}")
        # 验证之前只有 docstring 和注释
        has_only_docstring = True
        for j in range(i-1):
            prev = lines[j].strip()
            if prev and not prev.startswith('#') and not prev.startswith('"""') and not prev.startswith("'''") and prev not in ['', '"""', "'''"]:
                # 检查是否在 docstring 内
                if '整理下载文件夹' not in prev and '用法' not in prev and '不传路径' not in prev:
                    has_only_docstring = False
                    break
        if has_only_docstring:
            print("  ✓ from __future__ 导入位置正确（在 docstring 之后）")
        else:
            print("  ✗ from __future__ 导入位置可能不正确")
        break

# 显示文件开头和结尾
print("\n文件开头 5 行:")
for i, line in enumerate(lines[:5], 1):
    print(f"  {i}: {repr(line)}")

print("\n文件结尾 5 行:")
for i, line in enumerate(lines[-5:], start=len(lines)-4):
    print(f"  {i}: {repr(line)}")

print("\n" + "=" * 60)
if not issues:
    print("✅ 所有格式问题已修复！")
else:
    print("⚠ 仍存在格式问题，需要进一步修复")
print("=" * 60)
